// Guid is a 128-bit identifier in canonical (big-endian) byte order.
type Guid [16]byte

func (g Guid) String() string {
	h := fmt.Sprintf("%x", g[:])
	return h[0:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:32]
}

// ParseGuid accepts "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx", 32 hex digits, surrounding braces and a
// "guid:" prefix (the forms helios::Guid::parse accepts).
func ParseGuid(s string) (Guid, error) {
	var g Guid
	s = strings.TrimPrefix(s, "guid:")
	if len(s) >= 2 && s[0] == '{' && s[len(s)-1] == '}' {
		s = s[1 : len(s)-1]
	}
	if len(s) == 36 {
		if s[8] != '-' || s[13] != '-' || s[18] != '-' || s[23] != '-' {
			return g, fmt.Errorf("helios: invalid GUID %q", s)
		}
		s = s[0:8] + s[9:13] + s[14:18] + s[19:23] + s[24:]
	}
	if len(s) != 32 {
		return g, fmt.Errorf("helios: invalid GUID %q", s)
	}
	for i := 0; i < 16; i++ {
		v, err := strconv.ParseUint(s[2*i:2*i+2], 16, 8)
		if err != nil {
			return g, fmt.Errorf("helios: invalid GUID %q", s)
		}
		g[i] = byte(v)
	}
	return g, nil
}

func (g Guid) MarshalText() ([]byte, error) { return []byte(g.String()), nil }
func (g *Guid) UnmarshalText(b []byte) error {
	v, err := ParseGuid(string(b))
	if err != nil {
		return err
	}
	*g = v
	return nil
}

func readGuid(r *wireReader, wt int) (Guid, error) {
	var g Guid
	if wt != wireLen {
		return g, wireMismatch("Guid", wt, wireLen)
	}
	p, err := r.lenBytes()
	if err != nil {
		return g, err
	}
	if len(p) != 16 {
		return g, fmt.Errorf("%w: Guid: %d bytes, expected 16", ErrCorrupt, len(p))
	}
	copy(g[:], p)
	return g, nil
}

