// renameJSONKeys rewrites the members of a JSON object named by an @was alias to their current
// field names (the current name wins when both are present).
func renameJSONKeys(b []byte, renames map[string]string) ([]byte, error) {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(b, &obj); err != nil || obj == nil {
		return b, nil // not an object: let the struct decoder report it
	}
	changed := false
	for old, cur := range renames {
		if v, ok := obj[old]; ok {
			if _, has := obj[cur]; !has {
				obj[cur] = v
			}
			delete(obj, old)
			changed = true
		}
	}
	if !changed {
		return b, nil
	}
	return json.Marshal(obj)
}

