// Duration is a signed span in nanoseconds (like time.Duration). JSON: "500ms", "30d", ...
type Duration int64

var durationUnits = []struct {
	suffix string
	nanos  int64
}{{"d", 86400000000000}, {"h", 3600000000000}, {"m", 60000000000}, {"s", 1000000000}, {"ms", 1000000}, {"us", 1000}, {"ns", 1}}

func (d Duration) String() string {
	if d == 0 {
		return "0s"
	}
	for _, u := range durationUnits {
		if int64(d)%u.nanos == 0 {
			return strconv.FormatInt(int64(d)/u.nanos, 10) + u.suffix
		}
	}
	return strconv.FormatInt(int64(d), 10) + "ns"
}

// ParseDuration parses "<number><unit>" with units d, h, m, s, ms, us, ns (decimals allowed).
func ParseDuration(s string) (Duration, error) {
	orig := s
	neg := strings.HasPrefix(s, "-")
	s = strings.TrimPrefix(s, "-")
	i := 0
	for i < len(s) && (s[i] >= '0' && s[i] <= '9' || s[i] == '.') {
		i++
	}
	num, suffix := s[:i], s[i:]
	var unit int64
	for _, u := range durationUnits {
		if u.suffix == suffix {
			unit = u.nanos
		}
	}
	if num == "" || num == "." || unit == 0 {
		return 0, fmt.Errorf("helios: invalid duration %q", orig)
	}
	intPart, fracPart, _ := strings.Cut(num, ".")
	if strings.Contains(fracPart, ".") {
		return 0, fmt.Errorf("helios: invalid duration %q", orig)
	}
	var whole uint64
	if intPart != "" {
		v, err := strconv.ParseUint(intPart, 10, 64)
		if err != nil {
			return 0, fmt.Errorf("helios: invalid duration %q", orig)
		}
		whole = v
	}
	if whole > uint64(math.MaxInt64)/uint64(unit) {
		return 0, fmt.Errorf("helios: duration %q overflows", orig)
	}
	total := whole * uint64(unit)
	scale := uint64(unit)
	var frac uint64
	for _, c := range fracPart {
		digit := uint64(c - '0')
		if scale%10 == 0 {
			scale /= 10
			frac += digit * scale
		} else {
			n := digit * scale
			frac += n / 10
			if n%10 >= 5 {
				frac++
			}
			break
		}
	}
	total += frac
	if total > uint64(math.MaxInt64) {
		return 0, fmt.Errorf("helios: duration %q overflows", orig)
	}
	if neg {
		return Duration(-int64(total)), nil
	}
	return Duration(total), nil
}

func (d Duration) MarshalJSON() ([]byte, error) { return json.Marshal(d.String()) }
func (d *Duration) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err == nil {
		v, err := ParseDuration(s)
		if err != nil {
			return err
		}
		*d = v
		return nil
	}
	var seconds float64
	if err := json.Unmarshal(b, &seconds); err != nil || math.Abs(seconds) >= 9.2e9 {
		return fmt.Errorf("helios: duration must be a string like \"500ms\" or a number of seconds (|s| < 9.2e9)")
	}
	*d = Duration(math.Round(seconds * 1e9))
	return nil
}

